public class OrderService {
    private final PaymentGateway paymentGateway;

    public OrderService(PaymentGateway paymentGateway) {
        // Unchecked exception for contract violation (fail fast)
        this.paymentGateway = Objects.requireNonNull(paymentGateway, "PaymentGateway must not be null");
    }

    public void processOrder(Order order) {
        try {
            // Checked exception representing a recoverable environmental failure
            paymentGateway.charge(order.getTotalAmount());
        } catch (PaymentGatewayTimeoutException e) {
            // Meaningful recovery: log, queue for async retry, or trigger fallback
            throw new OrderProcessingException("Temporary payment failure, order queued for retry", e);
        }
    }
}
